L["STUCK_FILTER_ON_TIP"]       = "Click to show only these mails."
L["STUCK_FILTER_OFF_TIP"]      = "Click to show all mail again."
L["VIEW_HISTORY"]              = "History"
L["HISTORY_TIP_ONE"]           = "What Postbox collected on this character in the last %d day, newest first, with what it earned and spent."
L["HISTORY_TIP_OTHER"]         = "What Postbox collected on this character in the last %d days, newest first, with what it earned and spent."
