-- Shown ON a refused mail -- its row marker's tooltip and its detail metadata --
-- for as long as the mailbox stays open. %s is the game's own error text where
-- we could attribute it to this mail, and STUCK_GENERIC where we could not;
-- the generic half lists possibilities and never asserts a cause. Full bags are
-- never among them: they are not about the mail (STATUS_BAGS_FULL is).
L["STUCK_LINE"]                = "Not collected: %s"
L["STUCK_GENERIC"]             = "you may already have one, or as many as you can carry"
-- The bags are full and mail with items waits for room: the status line (%d is
