  -- Options
  L["OPT_TAB_COUNTS_TITLE"]      = "Afficher le nombre de courriers"
  L["OPT_TAB_COUNTS_DESC"]       = "Des nombres sur Boite et sur chaque bouton de collecte.\n\nBoite compte tous les courriers de la boite, lus compris ; un bouton compte ce qu'il recupererait. Dans tous les cas, l'onglet Courrier porte un point tant qu'il reste du courrier a recuperer."
  L["OPT_READ_MAIL_TITLE"]       = "Courrier lu"
  L["OPT_READ_MAIL_DESC"]        = "Ou va un courrier lu qui ne contient plus rien.\n\nSous la boite : apres le courrier a recuperer, sous un separateur qui reste au bas d'une longue liste, avec Tout supprimer ; clique sur le separateur pour les replier. Dans un onglet Termine : un segment a part a cote de Boite. Supprimer une fois traite : supprime des que Postbox en retire le dernier or ou objet, ou que tu cliques sur Retour apres l'avoir lu ; l'historique garde son texte. Le courrier lu deja present reste sous le separateur jusqu'a ce que tu le supprimes."
  L["OPT_READ_FOLD"]             = "Sous la boite"
  L["OPT_READ_TAB"]              = "Dans un onglet Termine"
  L["OPT_READ_DELETE"]           = "Supprimer une fois traite"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Garder l'historique"
  L["OPT_HISTORY_KEEP_DESC"]     = "Combien de jours de courrier recupere l'historique garde.\n\nPlus de jours donne un enregistrement plus lourd par personnage ; jamais plus de 1000 courriers. Jamais : l'historique est desactive, son bouton quitte l'onglet Courrier, et ce qu'il gardait est efface sur chaque personnage."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d jour"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d jours"
  L["OPT_HISTORY_NEVER"]         = "Jamais"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "Desactiver l'historique ?\n\nCe qu'il a garde est efface tout de suite sur chaque personnage. C'est irreversible."
  L["BTN_HISTORY_OFF"]           = "Desactiver"
  L["OPT_LARGER_ROWS_TITLE"]     = "Lignes de courrier plus grandes"
  L["OPT_LARGER_ROWS_DESC"]      = "Deux lignes par courrier, avec une icone plus grande et tous ses chiffres sous son nom.\n\nDesactive, chaque courrier tient sur une ligne et la liste en montre davantage."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Disposition des lignes"
  L["OPT_ROW_LAYOUT_DESC"]       = "Comment s'alignent les chiffres sur les lignes de courrier simples.\n\nL'historique, la Memoire du courrier et la boite d'un autre personnage utilisent toujours une seule ligne, et l'onglet Courrier aussi tant que les lignes de courrier plus grandes sont desactivees. Colonnes : chaque chiffre reste sous son en-tete, et un long sujet continue dans les colonnes que son courrier laisse vides. Compacte : les chiffres de chaque ligne se resserrent, loin du sujet, et le sujet prend la place."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Les lignes de courrier plus grandes sont activees : les lignes de l'onglet Courrier tiennent sur deux lignes et resserrent toujours la deuxieme. L'historique, la Memoire du courrier et la boite d'un autre personnage restent sur une ligne et suivent toujours ce reglage."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Colonnes"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Chaque chiffre reste sous son en-tete."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Compacte"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Les chiffres de chaque ligne se resserrent ; le sujet prend la place."
  L["ARRANGE_NOTE_PACKED"]       = "Compacte : un courrier qui ne l'a pas ne laisse pas de vide, et le sujet prend sa place."
  L["ARRANGE_LAYOUT_WHERE"]      = "Disposition des lignes en decide, dans l'apercu ou dans les options, onglet Courrier."
  L["ARRANGE_LANES_ON"]          = "Chaque chiffre garde sa colonne sur chaque ligne. Un long sujet continue dans les colonnes que son courrier laisse vides, jusqu'au premier chiffre du courrier."
  L["OPT_QUALITY_OFF"]           = "Desactive"
  L["OPT_QUALITY_ICON_TITLE"]    = "Qualite sur les icones"
  L["OPT_QUALITY_ICON_DESC"]     = "La marque de qualite d'artisanat sur le coin de l'icone d'un objet dans les listes de courrier.\n\nL'onglet Courrier, l'historique et la memoire du courrier la suivent tous."
  L["OPT_QUALITY_NAME_TITLE"]    = "Qualite pres du nom"
  L["OPT_QUALITY_NAME_DESC"]     = "Une marque de qualite d'artisanat a cote du nom d'un objet dans les listes de courrier, seule ou avec celle de l'icone.\n\nAvant le nom, les noms restent alignes. Apres, comme dans un lien du chat, la marque s'affiche toujours en entier : un nom long est raccourci pour lui faire place. L'onglet Courrier, l'historique et la memoire du courrier la suivent tous."
  L["OPT_QUALITY_NAME_BEFORE"]   = "Avant"
  L["OPT_QUALITY_NAME_AFTER"]    = "Apres"
  L["HISTORY_AGE_M"]             = "%d min"
  L["HISTORY_AGE_H"]             = "%d h"
  L["HISTORY_AGE_D"]             = "%d j"
  L["HISTORY_DATE_DM"]           = "{d} {m}"
  L["HISTORY_DATE_MD"]           = "{m} {d}"
  L["HISTORY_DATE_DM_YEAR"]      = "{d} {m} {y}"
  L["HISTORY_DATE_MD_YEAR"]      = "{m} {d} {y}"
  L["OPT_SLOTS_WORDS"]           = "Nombre et mot"
  L["OPT_SLOTS_NUMBER"]          = "Nombre seul"
  L["COL_READ_STUCK"]            = "Un courrier bloque, qui n'a pas pu etre recupere, affiche ici un triangle d'avertissement."
  L["OPT_PREVIEW_CLICK_TITLE"]   = "Le clic gauche ouvre le courrier"
  L["OPT_PREVIEW_CLICK_DESC"]    = "Le clic gauche ouvre le courrier et le clic droit le recupere.\n\nDesactive, les deux s'echangent : le clic gauche recupere et le clic droit ouvre sans recuperer."
  L["OPT_ATTACH_MAIL_TITLE"]     = "Joindre depuis Courrier"
  L["OPT_ATTACH_MAIL_DESC"]      = "Un clic droit sur un objet du sac dans l'onglet Courrier passe a Envoyer et le joint.\n\nDesactive, les objets s'y comportent normalement. L'onglet Envoyer joint dans les deux cas."
  L["OPT_KEEP_RECIPIENT_TITLE"]  = "Garder le destinataire"
  L["OPT_KEEP_RECIPIENT_DESC"]   = "Garde le nom dans le champ Destinataire une fois le courrier parti.\n\nLe suivant pour le meme personnage n'a pas a etre retape. Sujet, message, pieces jointes et or sont toujours effaces."
  L["OPT_CATEGORY_BUTTONS_TITLE"] = "Boutons de categorie"
  L["OPT_CATEGORY_BUTTONS_DESC"] = "Des boutons de collecte en un clic sous la liste, un par type de courrier.\n\nAchete, vendu, annule, expire, autre, de mes rerolls, et un par groupe de personnages. Desactive, seul Tous les courriers reste et la liste gagne la place."
  L["OPT_ROWS_HEADING"]          = "Lignes de courrier"
