  L["OPT_ROW_GOLD"]              = "Or"
  L["OPT_ROW_GOLD_DESC"]         = "L'or qu'apporte un courrier, en vert, et le cout d'un achat aux encheres, en rouge : choisis lesquels. Un prix C.R. s'affiche toujours, car Postbox n'en paie jamais un sans demander."
  L["OPT_ROW_SLOTS"]             = "Emplacements"
  L["OPT_ROW_SLOTS_DESC"]        = "Combien d'emplacements de piece jointe un courrier occupe encore. Masquee, le nombre passe dans l'infobulle de la ligne."
  L["OPT_ROW_EXPIRY"]            = "Temps restant"
  L["OPT_ROW_EXPIRY_DESC"]       = "Le temps qu'il reste a un courrier, en ambre sous trois jours (un pour un C.R.). Choisis quand la ligne l'affiche ; il est toujours dans l'infobulle."
  L["ARRANGE_TITLE"]             = "Organiser"
  L["ARRANGE_TIP"]               = "Deplace et masque les colonnes d'une ligne de courrier et les blocs sous la liste, et choisis ce qu'affichent Or, Temps restant et Emplacements.\n\nL'onglet Courrier et la Memoire du courrier partagent une disposition ; l'historique et les lignes de courrier plus grandes ont chacun la leur."
  L["ARRANGE_DONE"]              = "Termine"
  L["ARRANGE_GESTURE_OPEN"]      = "Clic pour organiser"
  L["OPT_ARRANGE_OFF"]           = "Ouvre d'abord une boite aux lettres, ou la Memoire du courrier."
  L["ARRANGE_RESET_CONFIRM_LARGER"] = "Revenir a la disposition par defaut ?\n\nLes colonnes des lignes de courrier plus grandes, les blocs sous la liste et les boutons de categorie reprennent leur place d'origine, tous affiches, et Or, Temps restant et Emplacements leur choix par defaut. La disposition des lignes ne change pas, et les lignes simples et l'Historique gardent leur propre disposition."
  L["ARRANGE_LAYOUT_LARGER"]     = "Les lignes de courrier plus grandes resserrent toujours les chiffres de leur deuxieme ligne."
  L["ARRANGE_NOTE_LARGE_SIDE"]   = "Sur les lignes de courrier plus grandes, elle se place au debut ou a la fin de la ligne. Glisse-la de l'autre cote du texte pour changer de cote."
  L["ARRANGE_NOTE_LARGE_SENDER"] = "Sur les lignes de courrier plus grandes, l'expediteur se place avant le sujet ou a la fin de la premiere ligne, ou sur la deuxieme ligne parmi les chiffres. Glisse-le vers le haut ou le bas pour changer de ligne."
  L["ARRANGE_NOTE_LARGE_SUBJECT"] = "Sur les lignes de courrier plus grandes, le sujet occupe la premiere ligne, a cote de l'expediteur, ou seul quand l'expediteur est sur la deuxieme ligne."
  L["ARRANGE_NOTE_LARGE_FIGURE"] = "Sur les lignes de courrier plus grandes, elle se place sur la deuxieme ligne, dans l'ordre qu'on y voit. Glisse-la le long de cette ligne."
  L["COL_AGE"]                   = "Recupere"
  L["COL_AGE_DESC"]              = "Il y a combien de temps chaque courrier a ete recupere, le plus recent en haut. Choisissez comment il s'ecrit."
  L["ARRANGE_LIST"]              = "Liste"
  L["ARRANGE_RESET_CONFIRM_HISTORY"] = "Revenir a la disposition par defaut de l'historique ?\n\nLes colonnes de l'historique reprennent leur place d'origine, toutes affichees, et la colonne Recupere son ecriture d'origine. L'or, les blocs sous la liste et les boutons de categorie sont partages avec la boite et restent tels quels : on les reinitialise depuis la boite."
  L["HISTORY_AGO_M"]             = "il y a %d min"
