  L["ARRANGE_RESET_CONFIRM"]     = "Revenir a la disposition par defaut ?\n\nLes colonnes, les blocs sous la liste et les boutons de categorie reprennent leur place d'origine, tous affiches, et Or, Temps restant et Emplacements leur choix par defaut. La disposition des lignes ne change pas, et l'Historique et les lignes de courrier plus grandes gardent leur propre disposition."
