  L["OPT_RESET_DEFAULTS"]        = "Reinitialiser les options"
  L["OPT_RESET_DEFAULTS_DESC"]   = "Reinitialise les reglages seuls, ou tout ce que Postbox conserve. Rien ne change avant ton choix."
  L["MSG_RESET_CONFIRM"]         = "Remettre Postbox par defaut ?\n\nReinitialiser les reglages : chaque option de cette fenetre revient a son etat d'origine, les fenetres de Postbox a leur taille et leur place de depart, et la disposition a celle par defaut : les colonnes des lignes de courrier, celles de l'Historique et des lignes de courrier plus grandes, les blocs sous la liste, ainsi que l'ordre des boutons de categorie et ceux que tu as masques. Conserves : tes destinataires (favoris, masques, notes et noms ajoutes par toi), tes destinataires recents, tes groupes de personnages, tes personnages masques, la Memoire du courrier et l'Historique, ainsi que l'icone de la minicarte, activee ou non.\n\nTout reinitialiser : tout cela est efface aussi, et l'icone de la minicarte est desactivee. Seule la liste de tes personnages est conservee. Une confirmation te sera d'abord demandee."
  L["BTN_RESET"]                 = "Reinitialiser"
  L["BTN_RESET_SETTINGS"]        = "Reinitialiser les reglages"
  L["BTN_RESET_EVERYTHING"]      = "Tout reinitialiser"
  L["MSG_RESET_ALL_CONFIRM"]     = "Tout reinitialiser ?\n\nChaque reglage revient a sa valeur par defaut et l'icone de la minicarte est desactivee. Effaces : tes destinataires (favoris, masques, notes et noms ajoutes par toi), tes destinataires recents, tes groupes de personnages, tes personnages masques, la Memoire du courrier et l'Historique.\n\nConservee : la liste de tes personnages. Postbox ne decouvre un personnage que lorsqu'il se connecte, et De mes rerolls, les groupes de personnages et la liste Alts de l'onglet Envoyer en dependent.\n\nCette action est irreversible."
  L["MSG_RESET_ALL_DONE"]        = "Tout est reinitialise. Postbox connait toujours tes personnages."
  L["MSG_RESET_WAIT_COLLECT"]    = "Attends que Postbox ait fini de recuperer ou de supprimer le courrier, puis reinitialise."
  L["MSG_RESET_WAIT_SEND"]       = "Attends que Postbox ait fini d'envoyer, puis reinitialise."
