  -- Empfaengerverwaltung
  L["RM_BTN_NOTE"]               = "Notiz"
  L["RM_TIP_NOTE"]               = "Ein paar eigene Worte zu diesem Charakter. Die Notiz steht in beiden Fenstern neben dem Namen."
  L["RM_TIP_ROW_FAV"]            = "Rechtsklick fuer Favorit an oder aus"
  L["RM_EMPTY_FILTER_HINT"]      = "Waehle oben eine andere Kategorie, oder Alle, um jeden Empfaenger zu sehen."
  L["RM_NOT_AVAILABLE"]          = "Empfaenger verwalten ist in diesem Build noch nicht verfuegbar."
  L["RM_OPT_BUTTON"]             = "Empfaenger verwalten"
  L["RM_OPT_BUTTON_DESC"]        = "Waehle, welche Charaktere Postbox beim Adressieren einer Post anbietet.\n\nBlende die aus, denen du nie schreibst, und mach die zu Favoriten, denen du schreibst."

  -- Optionen
  L["OPT_TAB_COUNTS_TITLE"]      = "Anzahl der Briefe anzeigen"
  L["OPT_TAB_COUNTS_DESC"]       = "Zahlen am Posteingang und an jedem Abhol-Button.\n\nPosteingang zaehlt jeden Brief im Postfach, gelesene eingeschlossen; ein Button zaehlt, was er abholen wuerde. In jedem Fall traegt der Post-Tab einen Punkt, solange Post abzuholen ist."
  L["OPT_READ_MAIL_TITLE"]       = "Gelesene Post"
  L["OPT_READ_MAIL_DESC"]        = "Wohin gelesene Post ohne Inhalt kommt.\n\nUnter dem Posteingang: nach der abzuholenden Post, unter einem Trenner, der am Fuss einer langen Liste stehen bleibt, mit Alle loeschen; ein Klick auf den Trenner klappt sie ein. Im Tab Erledigt: ein eigenes Segment neben Posteingang. Loeschen, wenn erledigt: geloescht, sobald Postbox das letzte Gold oder den letzten Gegenstand herausnimmt oder du nach dem Lesen auf Zurueck klickst; der Verlauf behaelt ihren Text. Bereits gelesene Post bleibt unter dem Trenner, bis du sie loeschst."
  L["OPT_READ_FOLD"]             = "Unter dem Posteingang"
  L["OPT_READ_TAB"]              = "Im Tab Erledigt"
  L["OPT_READ_DELETE"]           = "Loeschen, wenn erledigt"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Verlauf behalten"
  L["OPT_HISTORY_KEEP_DESC"]     = "Wie viele Tage abgeholter Post der Verlauf zeigt.\n\nMehr Tage heisst mehr gespeicherte Daten pro Charakter; nie mehr als 1000 Briefe. Nie: Der Verlauf ist aus, seine Schaltflaeche verschwindet aus dem Post-Tab, und was er behalten hat, wird bei jedem Charakter geloescht."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d Tag"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d Tage"
  L["OPT_HISTORY_NEVER"]         = "Nie"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "Verlauf ausschalten?\n\nWas er gespeichert hat, wird sofort auf jedem Charakter geloescht. Das laesst sich nicht rueckgaengig machen."
  L["BTN_HISTORY_OFF"]           = "Ausschalten"
  L["OPT_LARGER_ROWS_TITLE"]     = "Groessere Postzeilen"
  L["OPT_LARGER_ROWS_DESC"]      = "Zwei Zeilen je Brief, mit groesserem Symbol und allen Angaben unter dem Namen.\n\nAus, bekommt jeder Brief eine Zeile und die Liste zeigt mehr."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Zeilenlayout"
  L["OPT_ROW_LAYOUT_DESC"]       = "Wie die Angaben in einzeiligen Postzeilen stehen.\n\nVerlauf, Postgedaechtnis und der Briefkasten eines anderen Charakters sind immer einzeilig, der Post-Tab ebenfalls, solange groessere Postzeilen aus sind. Spalten: Jede Angabe bleibt unter ihrer Ueberschrift, und ein langer Betreff laeuft in die Spalten weiter, die sein Brief leer laesst. Kompakt: Die Angaben jeder Zeile ruecken zusammen, weg vom Betreff, und der Betreff bekommt den Platz."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Groessere Postzeilen sind an: Die Zeilen im Post-Tab sind zweizeilig und ruecken ihre zweite Zeile immer zusammen. Verlauf, Postgedaechtnis und der Briefkasten eines anderen Charakters bleiben einzeilig und folgen weiter dieser Wahl."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Spalten"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Jede Angabe bleibt unter ihrer Ueberschrift."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Kompakt"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Die Angaben jeder Zeile ruecken zusammen; der Betreff bekommt den Platz."
  L["ARRANGE_NOTE_PACKED"]       = "Kompakt: Ein Brief ohne sie laesst keine Luecke, und der Betreff bekommt ihren Platz."
  L["ARRANGE_LAYOUT_WHERE"]      = "Das entscheidet Zeilenlayout, in der Uebersicht oder in den Optionen, Post-Tab."
  L["ARRANGE_LANES_ON"]          = "Jede Angabe behaelt ihre Spalte in jeder Zeile. Ein langer Betreff laeuft in die Spalten weiter, die sein Brief leer laesst, bis zur ersten Angabe des Briefs."
  L["OPT_QUALITY_OFF"]           = "Aus"
  L["OPT_QUALITY_ICON_TITLE"]    = "Qualitaet auf Symbolen"
  L["OPT_QUALITY_ICON_DESC"]     = "Das Handwerksqualitaetssymbol in der Ecke des Gegenstandssymbols in den Postlisten.\n\nPost-Tab, Verlauf und Postgedaechtnis folgen der Wahl."
  L["OPT_QUALITY_NAME_TITLE"]    = "Qualitaet am Namen"
  L["OPT_QUALITY_NAME_DESC"]     = "Ein Handwerksqualitaetssymbol neben dem Namen eines Gegenstands in den Postlisten, allein oder mit dem auf dem Symbol.\n\nDavor bleiben die Namen buendig. Dahinter, wie im Chatlink, ist das Symbol immer ganz zu sehen: ein langer Name wird dafuer gekuerzt. Post-Tab, Verlauf und Postgedaechtnis folgen der Wahl."
  L["OPT_QUALITY_NAME_BEFORE"]   = "Davor"
  L["OPT_QUALITY_NAME_AFTER"]    = "Dahinter"
  L["HISTORY_AGE_M"]             = "%d Min."
  L["HISTORY_AGE_H"]             = "%d Std."
  L["HISTORY_AGE_D"]             = "%d Tg."
  L["HISTORY_DATE_DM"]           = "{d}. {m}"
  L["HISTORY_DATE_MD"]           = "{m} {d}"
  L["HISTORY_DATE_DM_YEAR"]      = "{d}. {m} {y}"
  L["HISTORY_DATE_MD_YEAR"]      = "{m} {d} {y}"
  L["OPT_SLOTS_WORDS"]           = "Zahl und Wort"
  L["OPT_SLOTS_NUMBER"]          = "Nur die Zahl"
  L["COL_READ_STUCK"]            = "Ein feststeckender Brief, der nicht abgeholt werden konnte, zeigt hier ein Warndreieck."
  L["OPT_PREVIEW_CLICK_TITLE"]   = "Linksklick oeffnet die Post"
  L["OPT_PREVIEW_CLICK_DESC"]    = "Linksklick oeffnet die Post und Rechtsklick holt sie ab.\n\nAusgeschaltet tauschen die beiden: Linksklick holt ab und Rechtsklick oeffnet ohne Abholen."
  L["OPT_ATTACH_MAIL_TITLE"]     = "Anhaengen im Post-Tab"
  L["OPT_ATTACH_MAIL_DESC"]      = "Ein Rechtsklick auf einen Beutelgegenstand im Post-Tab wechselt zu Senden und haengt ihn an.\n\nAusgeschaltet verhalten sich Gegenstaende dort normal. Im Senden-Tab wird so oder so angehaengt."
  L["OPT_KEEP_RECIPIENT_TITLE"]  = "Empfaenger behalten"
  L["OPT_KEEP_RECIPIENT_DESC"]   = "Laesst den Namen nach dem Senden im Empfaenger-Feld stehen.\n\nDie naechste Post an denselben Charakter muss nicht neu adressiert werden. Betreff, Nachricht, Anhaenge und Gold werden weiterhin geleert."
  L["OPT_CATEGORY_BUTTONS_TITLE"] = "Kategorie-Buttons zeigen"
  L["OPT_CATEGORY_BUTTONS_DESC"] = "Ein-Klick-Abhol-Buttons unter der Liste, einer je Art von Post.\n\nGekauft, verkauft, abgebrochen, abgelaufen, sonstige, von Twinks und einer je Charaktergruppe. Aus, bleibt nur Alle Post und die Liste bekommt den Platz."
  L["OPT_ROWS_HEADING"]          = "Postzeilen"
  L["OPT_GOLD_BOTH"]             = "Ein- und Ausgaben"
  L["OPT_GOLD_EARNED"]           = "Nur Einnahmen"
  L["OPT_GOLD_SPENT"]            = "Nur Ausgaben"
  L["OPT_EXPIRY_ALWAYS"]         = "Immer"
  L["OPT_EXPIRY_UNDER_ONE"]      = "Unter %d Tag"
  L["OPT_EXPIRY_UNDER_OTHER"]    = "Unter %d Tagen"
  L["COMPARTMENT_TIP"]           = "Klick fuer das Postgedaechtnis, den Briefkasten jedes Charakters · Rechtsklick fuer Optionen"
  L["OPT_ROW_GOLD"]              = "Gold"
  L["OPT_ROW_GOLD_DESC"]         = "Gold, das ein Brief bringt, in Gruen, und was ein Auktionskauf gekostet hat, in Rot: waehle, was. Ein Nachnahmepreis steht immer da, denn Postbox bezahlt nie einen, ohne zu fragen."
  L["OPT_ROW_SLOTS"]             = "Plaetze"
  L["OPT_ROW_SLOTS_DESC"]        = "Wie viele Anhangplaetze ein Brief noch belegt. Ausgeblendet steht die Zahl im Tooltip der Zeile."
  L["OPT_ROW_EXPIRY"]            = "Restzeit"
  L["OPT_ROW_EXPIRY_DESC"]       = "Wie lange ein Brief noch bleibt, in Bernstein unter drei Tagen (einem bei Nachnahme). Waehle, wann die Zeile es zeigt; im Tooltip steht es immer."
  L["ARRANGE_TITLE"]             = "Anordnen"
  L["ARRANGE_TIP"]               = "Verschiebe die Spalten einer Postzeile und die Bloecke unter der Liste, blende sie aus und waehle, was Gold, Restzeit und Plaetze zeigen.\n\nDer Post-Reiter und das Postgedaechtnis teilen sich eine Anordnung; der Verlauf und die groesseren Postzeilen haben je ihre eigene."
  L["ARRANGE_DONE"]              = "Fertig"
  L["ARRANGE_GESTURE_OPEN"]      = "Klick zum Anordnen"
  L["OPT_ARRANGE_OFF"]           = "Oeffne zuerst einen Briefkasten oder das Postgedaechtnis."
  L["ARRANGE_RESET_CONFIRM_LARGER"] = "Zurueck zur Standardanordnung?\n\nDie Spalten der groesseren Postzeilen, die Bloecke unter der Liste und die Kategorie-Buttons kehren an ihren urspruenglichen Platz zurueck, alle sichtbar, und Gold, Restzeit und Plaetze zu ihrer Standardwahl. Das Zeilenlayout bleibt, wie es ist, und einzeilige Postzeilen und der Verlauf behalten ihre eigene Anordnung."
  L["ARRANGE_LAYOUT_LARGER"]     = "Groessere Postzeilen ruecken die Angaben ihrer zweiten Zeile immer zusammen."
  L["ARRANGE_NOTE_LARGE_SIDE"]   = "In groesseren Postzeilen steht sie am Anfang oder am Ende der Zeile. Zieh sie ueber den Text, um die Seite zu wechseln."
  L["ARRANGE_NOTE_LARGE_SENDER"] = "In groesseren Postzeilen steht der Absender vor dem Betreff oder am Ende der ersten Zeile, oder in der zweiten Zeile zwischen den Angaben. Zieh ihn nach oben oder unten, um die Zeile zu wechseln."
  L["ARRANGE_NOTE_LARGE_SUBJECT"] = "In groesseren Postzeilen nimmt der Betreff die erste Zeile ein, neben dem Absender, oder allein, solange der Absender in der zweiten Zeile steht."
  L["ARRANGE_NOTE_LARGE_FIGURE"] = "In groesseren Postzeilen steht sie in der zweiten Zeile, in der Reihenfolge, die dort zu sehen ist. Zieh sie an dieser Zeile entlang."
  L["COL_AGE"]                   = "Abgeholt"
  L["COL_AGE_DESC"]              = "Wie lange die Abholung jeder Post her ist, die neueste oben. Waehle die Schreibweise."
  L["ARRANGE_LIST"]              = "Liste"
  L["ARRANGE_RESET_CONFIRM_HISTORY"] = "Zurueck zur Standardanordnung des Verlaufs?\n\nDie Spalten des Verlaufs kehren an ihren urspruenglichen Platz zurueck, alle sichtbar, und Abgeholt zu seiner urspruenglichen Schreibweise. Gold, die Bloecke unter der Liste und die Kategorie-Buttons teilt der Verlauf mit dem Posteingang: Sie bleiben, wie sie sind, und werden im Posteingang zurueckgesetzt."
  L["HISTORY_AGO_M"]             = "vor %d Min."
  L["HISTORY_AGO_H"]             = "vor %d Std."
  L["HISTORY_AGO_D"]             = "vor %d Tg."
  L["HISTORY_AGO_MINUTES_ONE"]   = "vor %d Minute"
  L["HISTORY_AGO_MINUTES_OTHER"] = "vor %d Minuten"
  L["HISTORY_AGO_HOURS_ONE"]     = "vor %d Stunde"
  L["HISTORY_AGO_HOURS_OTHER"]   = "vor %d Stunden"
  L["HISTORY_AGO_DAYS_ONE"]      = "vor %d Tag"
  L["HISTORY_AGO_DAYS_OTHER"]    = "vor %d Tagen"
  L["ARRANGE_DONE_TIP"]          = "Anordnen beenden. Jede Aenderung ist schon gespeichert."
  L["ARRANGE_RESET_CONFIRM"]     = "Zurueck zur Standardanordnung?\n\nDie Spalten, die Bloecke unter der Liste und die Kategorie-Buttons kehren an ihren urspruenglichen Platz zurueck, alle sichtbar, und Gold, Restzeit und Plaetze zu ihrer Standardwahl. Das Zeilenlayout bleibt, wie es ist, und der Verlauf und die groesseren Postzeilen behalten ihre eigene Anordnung."
  L["ARRANGE_BLOCK_TOTALS"]      = "Summen"
  L["ARRANGE_BLOCK_GRID"]        = "Kategorie-Buttons"
  L["ARRANGE_OVERVIEW"]          = "Zieh alles Umrandete, um es zu verschieben: eine Spalte an ihrer Ueberschrift oder an einer beliebigen Zeile, einen Block oder einen Button an sich selbst. Klick darauf fuer seine Optionen, Rechtsklick blendet es aus oder ein."
  L["ARRANGE_HIDDEN"]            = "Ausgeblendet"
  L["ARRANGE_HIDDEN_CLICK"]      = "Ausgeblendet · klicken zum Zeigen"
  L["ARRANGE_HIDDEN_NONE"]       = "Nichts."
  L["ARRANGE_SHOWN"]             = "Sichtbar"
  L["ARRANGE_HIDDEN_STATE"]      = "Ausgeblendet"
  L["ARRANGE_MOVE"]              = "Verschieben"
  L["ARRANGE_NOTE_LEFT"]         = "Links vom Betreff: sie behaelt ihren Platz in jeder Zeile, damit die Betreffe buendig bleiben."
  L["ARRANGE_NOTE_RIGHT"]        = "Rechts vom Betreff: sie behaelt ihre Spalte in jeder Zeile, leer bei einem Brief ohne sie. Ein langer Betreff laeuft in leere Spalten weiter, bis zur ersten Angabe des Briefs."
  L["ARRANGE_UNDER_LIST"]        = "Unter der Liste"
  L["ARRANGE_BLOCK_TOTALS_DESC"] = "Eingenommen und ausgegeben ueber die gelistete Post. Derselbe Schalter wie Summen zeigen in den Optionen."
  L["ARRANGE_BLOCK_ALL_DESC"]    = "Ein Klick holt alles Gelistete ab. Immer sichtbar."
  L["ARRANGE_BLOCK_HISTORY_DESC"] = "Sagt, wessen Post der Verlauf zeigt und wie weit er zurueckreicht. Immer sichtbar."
  L["ARRANGE_BLOCK_DONE_DESC"]   = "Ein Klick loescht jeden gelesenen Brief, in dem nichts mehr ist. Immer sichtbar."
  L["ARRANGE_BLOCK_ALT_DESC"]    = "Wessen Briefkasten das ist, wann er zuletzt gesehen wurde und wo du ihn abholst. Immer sichtbar."
  L["ARRANGE_BLOCK_GRID_DESC"]   = "Ein Abhol-Button je Art von Post und je Charaktergruppe. Derselbe Schalter wie Kategorie-Buttons zeigen in den Optionen."
  L["ARRANGE_GRID_FOLD_NOTE"]    = "Ausgeblendet stehen die Kategorie-Buttons nur beim Anordnen hier zusammengeklappt. Sie behalten ihre Reihenfolge und die von dir ausgeblendeten fuer ihre Rueckkehr."
  L["ARRANGE_RESET"]             = "Anordnung zuruecksetzen"
  L["ARRANGE_ESC_KEY"]           = "Esc"
  L["ARRANGE_ESC_FINISH"]        = "zum Beenden"
  L["ARRANGE_HEADING_EMPTY"]     = "Kein Brief in dieser Liste hat sie, aber sie behaelt ihren Platz."
  L["ARRANGE_PEG_TIP"]           = "Ziehen zum Verschieben · Klick oder Rechtsklick zum Einblenden"
  L["ARRANGE_SUBJECT_WHY"]       = "Warum er dort endet"
  L["ARRANGE_SUBJECT_RUN"]       = "Jede Zeile zeigt, wie weit ihr Betreff reicht: den eigenen Platz getoent, den Platz, den er sich von leeren Spalten leihen kann, schraffiert, und einen Strich, wo er endet."
