  L["PERF_REC_ON_DESC"]          = "Misst jeden Besuch am Briefkasten ab dem naechsten: das Oeffnen, das Fuellen des Posteingangs, Tabwechsel und das Schliessen. Bleibt nach einem /reload an, bis du es ausschaltest."
  L["PERF_REC_DETAIL_DESC"]      = "Wie An, dazu, was der Posteingang bei jedem Besuch enthielt und welche Gegenstandsdaten das Spiel dabei geladen hat. Etwas mehr Arbeit bei jedem Besuch."
  L["PERF_REC_CHAT"]             = "Leistungsaufzeichnung: %s."
  L["OPT_BUG_HINT"]              = "Strg+C kopiert den markierten Text."
  L["OPT_RESET_DEFAULTS"]        = "Auf Standard zuruecksetzen"
  L["OPT_RESET_DEFAULTS_DESC"]   = "Setzt nur die Einstellungen zurueck oder alles, was Postbox speichert. Nichts aendert sich, bevor du waehlst."
  L["MSG_RESET_CONFIRM"]         = "Postbox auf Standard zuruecksetzen?\n\nEinstellungen zuruecksetzen: Jede Option in diesem Fenster kehrt zum Auslieferungszustand zurueck, die Fenster von Postbox zu ihrer ersten Groesse und Position und die Anordnung zum Standard: die Spalten der Postzeilen, die eigenen des Verlaufs und der groesseren Postzeilen, die Bloecke unter der Liste sowie die Reihenfolge der Kategorie-Buttons und die, die du ausgeblendet hast. Erhalten bleiben: deine Empfaenger (Favoriten, ausgeblendete, Notizen und von dir hinzugefuegte Namen), deine letzten Empfaenger, deine Charaktergruppen, deine ausgeblendeten Charaktere, das Postgedaechtnis und der Verlauf sowie ob das Minikarten-Symbol an ist.\n\nAlles zuruecksetzen: All das wird ebenfalls geloescht, und das Minikarten-Symbol wird ausgeschaltet. Nur die Liste deiner Charaktere bleibt erhalten. Du wirst vorher noch einmal gefragt."
  L["BTN_RESET"]                 = "Zuruecksetzen"
  L["BTN_RESET_SETTINGS"]        = "Einstellungen zuruecksetzen"
  L["BTN_RESET_EVERYTHING"]      = "Alles zuruecksetzen"
  L["MSG_RESET_ALL_CONFIRM"]     = "Alles zuruecksetzen?\n\nJede Einstellung kehrt zu ihrem Standard zurueck, und das Minikarten-Symbol wird ausgeschaltet. Geloescht werden: deine Empfaenger (Favoriten, ausgeblendete, Notizen und von dir hinzugefuegte Namen), deine letzten Empfaenger, deine Charaktergruppen, deine ausgeblendeten Charaktere, das Postgedaechtnis und der Verlauf.\n\nErhalten bleibt: die Liste deiner Charaktere. Postbox lernt einen Charakter erst kennen, wenn er sich einloggt, und Von Twinks, die Charaktergruppen und die Liste Alts im Senden-Tab haengen davon ab.\n\nDas laesst sich nicht rueckgaengig machen."
  L["MSG_RESET_ALL_DONE"]        = "Alles ist zurueckgesetzt. Postbox kennt deine Charaktere weiterhin."
  L["MSG_RESET_WAIT_COLLECT"]    = "Warte, bis Postbox mit dem Abholen oder Loeschen der Post fertig ist, und setze dann zurueck."
  L["MSG_RESET_WAIT_SEND"]       = "Warte, bis Postbox mit dem Senden fertig ist, und setze dann zurueck."
