  L["MINIMAP_TIP_UNLOCK"]        = "Alt-Klick zum Entsperren"
  L["OPT_MINIMAP_LOCK_TITLE"]    = "Position sperren"
  L["OPT_MINIMAP_LOCK_DESC"]     = "Verhindert, dass Umschalt-Ziehen das Symbol verschiebt - kein versehentliches Verrutschen.\n\nEin Alt-Klick auf das Symbol sperrt und entsperrt es ebenfalls."
  L["OPT_MEMORY_TITLE"]          = "Postgedaechtnis"
  L["OPT_MEMORY_DESC"]           = "Merkt sich, was im Briefkasten jedes Charakters beim letzten Besuch lag.\n\nFern vom Briefkasten zeigt es das Minikartensymbol, das Addon-Fach oder /postbox mail; am Briefkasten die Schaltflaeche Charaktere neben der Suche im Post-Tab. Aus, wird nichts aufgezeichnet."
