  L["PICKER_SHOW_TIP"]           = "Klick nimmt ihn wieder in Charakterliste, Suche und Warnungen auf"
  L["HIDDEN_TITLE"]              = "Ausgeblendete Charaktere"
  L["HIDDEN_DESC"]               = "Fehlen in der Charakterliste, in der Suche ueber alle Charaktere und in den Warnungen.\n\nPostbox merkt sich ihre Post weiter: Blendest du einen wieder ein, ist alles wieder da. Rechtsklick auf einen Namen in der Charakterliste blendet ihn aus."
  L["OPT_HIDDEN_NONE"]           = "Keine"
  L["OPT_HIDDEN_SHOW_ALL"]       = "Alle einblenden"
  L["OPT_HIDDEN_SHOW_ALL_DESC"]  = "Nimmt jeden ausgeblendeten Charakter wieder in die Charakterliste, die Suche und die Warnungen auf."
  L["MEMORY_NO_OTHERS_HIDDEN"]   = "Keiner deiner anderen Charaktere hat Post, die sich zeigen laesst, ausser denen, die du ausgeblendet hast. Blende sie in den Postbox-Optionen unter Postgedaechtnis wieder ein."
  L["PICKER_BACK_HINT"]          = "Rechtsklick zurueck zu deinem Briefkasten"
