  L["MEMORY_NO_OTHERS"]          = "Keiner deiner anderen Charaktere hat Post, die sich zeigen laesst."
  L["OPT_MINIMAP_ACCENT_TITLE"]  = "Akzent"
  L["OPT_MINIMAP_ACCENT_DESC"]   = "Faerbt das Leuchten und jeden Symbolstil, der Einfaerben unterstuetzt, in Postbox' Akzentfarbe.\n\nDieselbe wie in den Fenstern: der Akzent deines Host-UIs bei aktivem Skin, sonst Postbox' eigenes Gold."
