  -- Opciones
  L["OPT_TAB_COUNTS_TITLE"]      = "Mostrar los recuentos de correo"
  L["OPT_TAB_COUNTS_DESC"]       = "Numeros en Buzon y en cada boton de recogida.\n\nBuzon cuenta todos los correos del buzon, leidos incluidos; un boton cuenta lo que recogeria. En cualquier caso, la pestana Correo lleva un punto mientras quede correo por recoger."
  L["OPT_READ_MAIL_TITLE"]       = "Correo leido"
  L["OPT_READ_MAIL_DESC"]        = "Adonde va un correo leido que ya no contiene nada.\n\nBajo el buzon: tras el correo por recoger, bajo un separador que se queda al pie de una lista larga, con Borrar todo; haz clic en el separador para plegarlos. En una pestana Hecho: un segmento propio junto a Buzon. Borrar al terminar: se borra en cuanto Postbox saca el ultimo oro u objeto, o pulsas Volver tras leerlo; el historial guarda su texto. El correo leido que ya estaba queda bajo el separador hasta que lo borres."
  L["OPT_READ_FOLD"]             = "Bajo el buzon"
  L["OPT_READ_TAB"]              = "En una pestana Hecho"
  L["OPT_READ_DELETE"]           = "Borrar al terminar"
  L["OPT_HISTORY_KEEP_TITLE"]    = "Guardar historial"
  L["OPT_HISTORY_KEEP_DESC"]     = "Cuantos dias de correo recogido guarda el historial.\n\nMas dias significa un registro mayor por personaje; nunca mas de 1000 correos. Nunca: el historial se desactiva, su boton sale de la pestana Correo y lo que guardaba se borra en todos los personajes."
  L["OPT_HISTORY_DAYS_ONE"]      = "%d dia"
  L["OPT_HISTORY_DAYS_OTHER"]    = "%d dias"
  L["OPT_HISTORY_NEVER"]         = "Nunca"
  L["MSG_HISTORY_OFF_CONFIRM"]   = "Desactivar el historial?\n\nLo que ha guardado se borra ahora en todos los personajes. No se puede deshacer."
  L["BTN_HISTORY_OFF"]           = "Desactivar"
  L["OPT_LARGER_ROWS_TITLE"]     = "Filas de correo mas grandes"
  L["OPT_LARGER_ROWS_DESC"]      = "Dos lineas por correo, con un icono mayor y todas sus cifras bajo el nombre.\n\nDesactivado, cada correo ocupa una linea y la lista muestra mas."
  L["OPT_ROW_LAYOUT_TITLE"]      = "Diseno de filas"
  L["OPT_ROW_LAYOUT_DESC"]       = "Como se alinean las cifras en las filas de correo de una linea.\n\nEl historial, la Memoria del correo y el buzon de otro personaje usan siempre una linea, y la pestana Correo tambien mientras las filas de correo mas grandes estan desactivadas. Columnas: cada cifra queda bajo su encabezado, y un asunto largo sigue por las columnas que su correo deja vacias. Compacto: las cifras de cada fila se juntan, lejos del asunto, y el asunto se queda el espacio."
  L["OPT_ROW_LAYOUT_LARGER"]     = "Las filas de correo mas grandes estan activadas: las filas de la pestana Correo ocupan dos lineas y siempre juntan la segunda. El historial, la Memoria del correo y el buzon de otro personaje siguen en una linea y siguen esta opcion."
  L["OPT_ROW_LAYOUT_COLUMNS"]    = "Columnas"
  L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Cada cifra queda bajo su encabezado."
  L["OPT_ROW_LAYOUT_PACKED"]     = "Compacto"
  L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Las cifras de cada fila se juntan; el asunto se queda el espacio."
  L["ARRANGE_NOTE_PACKED"]       = "Compacto: un correo sin ella no deja hueco, y el asunto ocupa su espacio."
  L["ARRANGE_LAYOUT_WHERE"]      = "Lo decide Diseno de filas, en la vista general o en las opciones, pestana Correo."
  L["ARRANGE_LANES_ON"]          = "Cada cifra conserva su columna en cada fila. Un asunto largo sigue por las columnas que su correo deja vacias, hasta la primera cifra del correo."
  L["OPT_QUALITY_OFF"]           = "Desactivado"
  L["OPT_QUALITY_ICON_TITLE"]    = "Calidad en los iconos"
  L["OPT_QUALITY_ICON_DESC"]     = "La marca de calidad de artesania en la esquina del icono de un objeto en las listas de correo.\n\nLa pestana Correo, el historial y la memoria del correo la siguen."
  L["OPT_QUALITY_NAME_TITLE"]    = "Calidad junto al nombre"
  L["OPT_QUALITY_NAME_DESC"]     = "Una marca de calidad de artesania junto al nombre de un objeto en las listas de correo, sola o con la del icono.\n\nAntes del nombre, los nombres siguen alineados. Despues, como en un enlace del chat, la marca siempre se ve entera: un nombre largo se acorta para dejarle sitio. La pestana Correo, el historial y la memoria del correo la siguen."
  L["OPT_QUALITY_NAME_BEFORE"]   = "Antes"
  L["OPT_QUALITY_NAME_AFTER"]    = "Despues"
  L["HISTORY_AGE_M"]             = "%d min"
  L["HISTORY_AGE_H"]             = "%d h"
  L["HISTORY_AGE_D"]             = "%d d"
  L["HISTORY_DATE_DM"]           = "{d} {m}"
  L["HISTORY_DATE_MD"]           = "{m} {d}"
  L["HISTORY_DATE_DM_YEAR"]      = "{d} {m} {y}"
  L["HISTORY_DATE_MD_YEAR"]      = "{m} {d} {y}"
  L["OPT_SLOTS_WORDS"]           = "Numero y palabra"
  L["OPT_SLOTS_NUMBER"]          = "Solo el numero"
  L["COL_READ_STUCK"]            = "Un correo atascado, que no se pudo recoger, muestra aqui un triangulo de aviso."
  L["OPT_PREVIEW_CLICK_TITLE"]   = "El clic izquierdo abre el correo"
  L["OPT_PREVIEW_CLICK_DESC"]    = "El clic izquierdo abre el correo y el clic derecho lo recoge.\n\nDesactivado, se intercambian: el clic izquierdo recoge y el derecho abre sin recoger."
  L["OPT_ATTACH_MAIL_TITLE"]     = "Adjuntar desde Correo"
  L["OPT_ATTACH_MAIL_DESC"]      = "El clic derecho en un objeto de la bolsa en la pestana Correo cambia a Enviar y lo adjunta.\n\nDesactivado, los objetos se comportan alli con normalidad. La pestana Enviar adjunta en ambos casos."
  L["OPT_KEEP_RECIPIENT_TITLE"]  = "Mantener destinatario"
  L["OPT_KEEP_RECIPIENT_DESC"]   = "Deja el nombre en el campo Destinatario una vez enviado el correo.\n\nEl siguiente al mismo personaje no hay que volver a escribirlo. Asunto, mensaje, adjuntos y oro se siguen vaciando."
  L["OPT_CATEGORY_BUTTONS_TITLE"] = "Botones de categoria"
  L["OPT_CATEGORY_BUTTONS_DESC"] = "Botones de recogida de un clic bajo la lista, uno por cada tipo de correo.\n\nComprado, vendido, cancelado, expirado, otros, de mis alters y uno por cada grupo de personajes. Desactivado, solo queda Todo el correo y la lista gana el espacio."
  L["OPT_ROWS_HEADING"]          = "Filas de correo"
  L["OPT_GOLD_BOTH"]             = "Ganado y gastado"
  L["OPT_GOLD_EARNED"]           = "Solo ganado"
  L["OPT_GOLD_SPENT"]            = "Solo gastado"
  L["OPT_EXPIRY_ALWAYS"]         = "Siempre"
  L["OPT_EXPIRY_UNDER_ONE"]      = "Menos de %d dia"
  L["OPT_EXPIRY_UNDER_OTHER"]    = "Menos de %d dias"
  L["COMPARTMENT_TIP"]           = "Clic para la memoria del correo, el buzon de cada personaje · Clic derecho para opciones"
  L["OPT_ROW_GOLD"]              = "Oro"
  L["OPT_ROW_GOLD_DESC"]         = "El oro que trae un correo, en verde, y lo que costo una compra en la subasta, en rojo: elige cual. Un precio C.R. siempre se muestra, porque Postbox nunca paga uno sin preguntar."
  L["OPT_ROW_SLOTS"]             = "Espacios"
  L["OPT_ROW_SLOTS_DESC"]        = "Cuantos espacios de adjuntos ocupa aun un correo. Oculta, el numero pasa a la informacion de la fila."
  L["OPT_ROW_EXPIRY"]            = "Tiempo restante"
  L["OPT_ROW_EXPIRY_DESC"]       = "Cuanto le queda a un correo, en ambar por debajo de tres dias (uno para C.R.). Elige cuando lo muestra la fila; siempre aparece en su informacion."
  L["ARRANGE_TITLE"]             = "Ordenar"
  L["ARRANGE_TIP"]               = "Mueve y oculta las columnas de una fila de correo y los bloques bajo la lista, y elige lo que muestran Oro, Tiempo restante y Espacios.\n\nLa pestana Correo y la Memoria del correo comparten una disposicion; el historial y las filas de correo mas grandes tienen cada uno la suya."
  L["ARRANGE_DONE"]              = "Hecho"
  L["ARRANGE_GESTURE_OPEN"]      = "Clic para ordenar"
  L["OPT_ARRANGE_OFF"]           = "Abre primero un buzon, o la Memoria del correo."
  L["ARRANGE_RESET_CONFIRM_LARGER"] = "Volver a la disposicion por defecto?\n\nLas columnas de las filas de correo mas grandes, los bloques bajo la lista y los botones de categoria vuelven a su sitio de origen, todos visibles, y Oro, Tiempo restante y Espacios a su opcion por defecto. El diseno de filas se queda como esta, y las filas de una linea y el Historial conservan su propia disposicion."
  L["ARRANGE_LAYOUT_LARGER"]     = "Las filas de correo mas grandes siempre juntan las cifras de su segunda linea."
  L["ARRANGE_NOTE_LARGE_SIDE"]   = "En las filas de correo mas grandes se coloca al principio o al final de la fila. Arrastrala al otro lado del texto para cambiar de lado."
  L["ARRANGE_NOTE_LARGE_SENDER"] = "En las filas de correo mas grandes el remitente va antes del asunto o al final de la primera linea, o en la segunda linea entre las cifras. Arrastralo hacia arriba o hacia abajo para cambiar de linea."
  L["ARRANGE_NOTE_LARGE_SUBJECT"] = "En las filas de correo mas grandes el asunto ocupa la primera linea, junto al remitente, o solo mientras el remitente esta en la segunda linea."
  L["ARRANGE_NOTE_LARGE_FIGURE"] = "En las filas de correo mas grandes va en la segunda linea, en el orden que se ve alli. Arrastrala a lo largo de esa linea."
  L["COL_AGE"]                   = "Recogido"
  L["COL_AGE_DESC"]              = "Cuanto hace que se recogio cada correo, el mas reciente arriba. Elige como se escribe."
  L["ARRANGE_LIST"]              = "Lista"
  L["ARRANGE_RESET_CONFIRM_HISTORY"] = "Volver a la disposicion por defecto del historial?\n\nLas columnas del historial vuelven a su sitio de origen, todas visibles, y Recogido a como se escribia al principio. El oro, los bloques bajo la lista y los botones de categoria se comparten con el buzon y se quedan como estan: se restablecen desde el buzon."
  L["HISTORY_AGO_M"]             = "hace %d min"
  L["HISTORY_AGO_H"]             = "hace %d h"
  L["HISTORY_AGO_D"]             = "hace %d d"
  L["HISTORY_AGO_MINUTES_ONE"]   = "hace %d minuto"
  L["HISTORY_AGO_MINUTES_OTHER"] = "hace %d minutos"
  L["HISTORY_AGO_HOURS_ONE"]     = "hace %d hora"
  L["HISTORY_AGO_HOURS_OTHER"]   = "hace %d horas"
  L["HISTORY_AGO_DAYS_ONE"]      = "hace %d dia"
  L["HISTORY_AGO_DAYS_OTHER"]    = "hace %d dias"
  L["ARRANGE_DONE_TIP"]          = "Terminar de ordenar. Cada cambio ya esta guardado."
  L["ARRANGE_RESET_CONFIRM"]     = "Volver a la disposicion por defecto?\n\nLas columnas, los bloques bajo la lista y los botones de categoria vuelven a su sitio de origen, todos visibles, y Oro, Tiempo restante y Espacios a su opcion por defecto. El diseno de filas se queda como esta, y el Historial y las filas de correo mas grandes conservan su propia disposicion."
  L["ARRANGE_BLOCK_TOTALS"]      = "Totales"
  L["ARRANGE_BLOCK_GRID"]        = "Botones de categoria"
  L["ARRANGE_OVERVIEW"]          = "Arrastra cualquier cosa con contorno para moverla: una columna por su encabezado o por cualquier fila, un bloque o un boton por si mismo. Haz clic en uno para ver sus opciones, y clic derecho para ocultarlo o mostrarlo."
  L["ARRANGE_HIDDEN"]            = "Ocultos"
  L["ARRANGE_HIDDEN_CLICK"]      = "Ocultos · clic para mostrar"
  L["ARRANGE_HIDDEN_NONE"]       = "Nada."
  L["ARRANGE_SHOWN"]             = "Visible"
  L["ARRANGE_HIDDEN_STATE"]      = "Oculto"
  L["ARRANGE_MOVE"]              = "Mover"
  L["ARRANGE_NOTE_LEFT"]         = "A la izquierda del asunto: conserva su espacio en cada fila, para que los asuntos sigan alineados."
  L["ARRANGE_NOTE_RIGHT"]        = "A la derecha del asunto: conserva su columna en cada fila, vacia en un correo que no la tiene. Un asunto largo sigue por las columnas vacias, hasta la primera cifra del correo."
  L["ARRANGE_UNDER_LIST"]        = "Bajo la lista"
  L["ARRANGE_BLOCK_TOTALS_DESC"] = "Ganado y gastado en el correo listado. El mismo ajuste que Totales en las opciones."
  L["ARRANGE_BLOCK_ALL_DESC"]    = "Un clic recoge todo lo listado. Siempre visible."
  L["ARRANGE_BLOCK_HISTORY_DESC"] = "Dice de quien es el correo que lista el historial y hasta cuando se remonta. Siempre visible."
  L["ARRANGE_BLOCK_DONE_DESC"]   = "Un clic borra cada correo leido que ya no contiene nada. Siempre visible."
  L["ARRANGE_BLOCK_ALT_DESC"]    = "De quien es este buzon, cuando se vio por ultima vez y donde recogerlo. Siempre visible."
  L["ARRANGE_BLOCK_GRID_DESC"]   = "Un boton de recogida por cada tipo de correo y cada grupo de personajes. El mismo ajuste que Botones de categoria en las opciones."
  L["ARRANGE_GRID_FOLD_NOTE"]    = "Ocultos, los botones de categoria quedan plegados aqui solo mientras ordenas. Conservan su orden, y los que ocultaste, para cuando vuelvan."
  L["ARRANGE_RESET"]             = "Restablecer disposicion"
  L["ARRANGE_ESC_KEY"]           = "Esc"
  L["ARRANGE_ESC_FINISH"]        = "para terminar"
  L["ARRANGE_HEADING_EMPTY"]     = "Ningun correo listado aqui la tiene, pero conserva su sitio."
  L["ARRANGE_PEG_TIP"]           = "Arrastra para mover · Clic o clic derecho para mostrar"
  L["ARRANGE_SUBJECT_WHY"]       = "Por que se detiene ahi"
  L["ARRANGE_SUBJECT_RUN"]       = "Cada fila muestra hasta donde llega su asunto: su propio espacio coloreado, el espacio que puede tomar de las columnas vacias rayado, y una marca donde se detiene."
  L["ARRANGE_BACK"]              = "Volver"
  L["ARRANGE_ESC_CANCEL"]        = "para cancelar"
  L["ARRANGE_GESTURE_HIDE"]      = "Arrastra para mover · Clic para opciones · Clic derecho para ocultar"
  L["ARRANGE_GESTURE_SHOW"]      = "Arrastra para mover · Clic para opciones · Clic derecho para mostrar"
  L["ARRANGE_GESTURE_FIXED"]     = "Arrastra para mover · Clic para opciones"
  L["ARRANGE_GESTURE_FINISH"]    = "Clic o Escape para terminar"
  L["ARRANGE_GESTURE_DONE"]      = "Clic o Escape para terminar · Clic derecho para restablecer"
  L["ARRANGE_GESTURE_BACK"]      = "Clic o Escape para volver a la vista general"
  L["ARRANGE_BUTTON_DESC"]       = "Un clic recoge el correo que nombra."
  L["ARRANGE_BUTTON_GROUP_DESC"] = "Un clic recoge el correo de los personajes de este grupo."
  L["ARRANGE_UP_GRID"]           = "En los botones de categoria"
  L["ARRANGE_GROUPS_OPEN"]       = "Grupos de personajes..."
  L["ARRANGE_TOTALS_FOLD_NOTE"]  = "Ocultos, los totales quedan plegados aqui solo mientras ordenas."
  L["OPT_TOTALS_TITLE"]          = "Totales"
  L["OPT_TOTALS_DESC"]           = "Ganado y gastado en el correo listado, en una banda bajo la lista.\n\nDesactivado, los bloques de debajo se juntan y la lista gana el espacio."
  L["GROUPS_BUTTONS_OFF"]        = "Los botones de categoria estan desactivados, asi que ningun grupo tiene boton. Activa Botones de categoria en las opciones, pestana Correo, para recuperarlos."
  L["COL_READ"]                  = "Marca de leido"
  L["COL_READ_DESC"]             = "Un punto verde mientras un correo no se ha leido. Un correo atascado, que no se pudo recoger, muestra en su lugar un triangulo de aviso."
  L["COL_ICON"]                  = "Icono"
  L["COL_ICON_DESC"]             = "El objeto que trae un correo, o una carta o monedas. Pasa el raton por encima en la lista para ver la informacion del objeto."
  L["COL_SENDER"]                = "Remitente"
  L["COL_SENDER_DESC"]           = "Quien envio el correo. Un correo de subasta dice en su lugar lo que paso: vendido, ganado, expirado o cancelado. Oculto, pasa a la informacion de la fila."
  L["COL_SUBJECT"]               = "Asunto"
