  L["OPT_RESET_DEFAULTS"]        = "Restablecer opciones"
  L["OPT_RESET_DEFAULTS_DESC"]   = "Restablece solo los ajustes, o todo lo que guarda Postbox. Nada cambia hasta que elijas."
  L["MSG_RESET_CONFIRM"]         = "Restablecer Postbox?\n\nRestablecer ajustes: cada opcion de esta ventana vuelve a su estado original, las ventanas de Postbox a su tamano y lugar iniciales, y la disposicion a la de por defecto: las columnas de las filas de correo, las propias del Historial y de las filas de correo mas grandes, los bloques bajo la lista, y el orden de los botones de categoria y los que ocultaste. Se conservan: tus destinatarios (favoritos, ocultos, notas y nombres anadidos por ti), tus destinatarios recientes, tus grupos de personajes, tus personajes ocultos, la Memoria del correo y el Historial, y si el icono del minimapa esta activado.\n\nRestablecer todo: tambien se borra todo eso, y el icono del minimapa se desactiva. Solo se conserva la lista de tus personajes. Antes se te pedira confirmacion."
  L["BTN_RESET"]                 = "Restablecer"
  L["BTN_RESET_SETTINGS"]        = "Restablecer ajustes"
  L["BTN_RESET_EVERYTHING"]      = "Restablecer todo"
  L["MSG_RESET_ALL_CONFIRM"]     = "Restablecer todo?\n\nCada ajuste vuelve a su valor por defecto y el icono del minimapa se desactiva. Se borran: tus destinatarios (favoritos, ocultos, notas y nombres anadidos por ti), tus destinatarios recientes, tus grupos de personajes, tus personajes ocultos, la Memoria del correo y el Historial.\n\nSe conserva: la lista de tus personajes. Postbox solo conoce un personaje cuando este inicia sesion, y De mis alters, los grupos de personajes y la lista Alts de la pestana Enviar dependen de ella.\n\nEsto no se puede deshacer."
  L["MSG_RESET_ALL_DONE"]        = "Todo restablecido. Postbox sigue conociendo a tus personajes."
