L["MSG_HISTORY_OFF_CONFIRM"]   = "Выключить историю?\n\nВсё, что она хранит, сразу удалится на всех персонажах. Это необратимо."
L["BTN_HISTORY_OFF"]           = "Выключить"
L["OPT_LARGER_ROWS_TITLE"]     = "Крупные строки писем"
L["OPT_LARGER_ROWS_DESC"]      = "Две строки на письмо: значок крупнее, а все данные — под названием.\n\nВыключено — каждое письмо в одну строку, и в списке помещается больше."
L["OPT_ROW_LAYOUT_TITLE"]      = "Вид строк"
L["OPT_ROW_LAYOUT_DESC"]       = "Как выстраиваются значения в однострочных строках писем.\n\nИстория, память почты и ящик другого персонажа всегда однострочные, а вкладка «Почта» — пока крупные строки писем выключены. Столбцы: каждое значение стоит под своим заголовком, а длинная тема продолжается в столбцы, пустые у её письма. Плотно: значения каждой строки сдвигаются вместе, в сторону от темы, и тема получает место."
L["OPT_ROW_LAYOUT_LARGER"]     = "Крупные строки писем включены: строки вкладки «Почта» занимают две строки и всегда сжимают вторую. История, память почты и ящик другого персонажа остаются однострочными и по-прежнему следуют этому выбору."
L["OPT_ROW_LAYOUT_COLUMNS"]    = "Столбцы"
L["OPT_ROW_LAYOUT_COLUMNS_DESC"] = "Каждое значение стоит под своим заголовком."
L["OPT_ROW_LAYOUT_PACKED"]     = "Плотно"
L["OPT_ROW_LAYOUT_PACKED_DESC"] = "Значения каждой строки сдвигаются вместе; тема получает место."
L["ARRANGE_NOTE_PACKED"]       = "Плотно: у письма без него не остаётся пустого места, и тема занимает его место."
L["ARRANGE_LAYOUT_WHERE"]      = "Это задаёт «Вид строк» — в обзоре или в настройках, на вкладке «Почта»."
L["ARRANGE_LANES_ON"]          = "Каждое значение сохраняет свой столбец в каждой строке. Длинная тема продолжается в столбцы, пустые у её письма, до первого значения письма."
L["OPT_QUALITY_OFF"]           = "Выкл."
