L["MSG_RESET_CONFIRM"]         = "Сбросить Postbox к исходному состоянию?\n\nСбросить настройки: все параметры в этом окне вернутся к исходным, окна Postbox — к исходным размеру и положению, а расстановка — к расстановке по умолчанию: столбцы строк писем, собственные расстановки истории и крупных строк писем, блоки под списком, а также порядок кнопок категорий и скрытые из них. Сохранятся: получатели (избранные, скрытые, заметки и добавленные вами имена), недавние получатели, группы персонажей, скрытые персонажи, память почты и история, а также то, включён ли значок на миникарте.\n\nСбросить всё: всё это тоже будет стёрто, а значок на миникарте — выключен. Сохранится только список ваших персонажей. Перед этим вас спросят ещё раз."
