  L["MSG_RESET_CONFIRM"]       = "將 Postbox 恢復為預設狀態？\n\n重設設定：此視窗中的每個選項都會恢復為初始狀態，Postbox 的視窗會恢復到初始的大小和位置，排列也會恢復預設：郵件列的欄位、歷史和較大郵件列各自的排列、清單下方的區塊，以及類別按鈕的順序和你隱藏的按鈕。以下內容會保留：你的收件者（最愛、隱藏、備註和你新增的名字）、最近的收件者、你的角色群組、已隱藏的角色、郵件記憶和歷史，以及小地圖圖示是否開啟。\n\n全部重設：以上內容也會一併清除，小地圖圖示會關閉。只保留你的角色清單。執行前會再次確認。"
